edits.before:
if (self.isVisible()) {
    switch(e.keyCode){
        case 13:
        case 27:
            if (opts.field) {
                opts.field.blur();
            }
            break;
        case 37:
            self.adjustDate('subtract', 1);
            break;
        case 38:
            self.adjustDate('subtract', 7);
            break;
        case 39:
            self.adjustDate('add', 1);
            break;
        case 40:
            self.adjustDate('add', 7);
            break;
        case 8:
        case 46:
            self.setDate(null);
            break;
    }
}

edits.after:
if (self.isVisible()) {
    function isAllowedDate(date) {
        if (!isDate(date)) return false;
        if (self._o.minDate && date < self._o.minDate) return false;
        if (self._o.maxDate && date > self._o.maxDate) return false;
        if (self._o.disableWeekends && isWeekend(date)) return false;
        if (self._o.disableDayFn && self._o.disableDayFn(date)) return false;
        return true;
    }
    switch(e.keyCode){
        case 13:
        case 27:
            if (opts.field) {
                opts.field.blur();
            }
            break;
        case 37:
            var newDate = self.getDate() || new Date();
            do {
                newDate = new Date(newDate.valueOf() - 24*60*60*1000);
            } while (!isAllowedDate(newDate));
            self.setDate(newDate);
            break;
        case 38:
            var newDate = self.getDate() || new Date();
            do {
                newDate = new Date(newDate.valueOf() - 7*24*60*60*1000);
            } while (!isAllowedDate(newDate));
            self.setDate(newDate);
            break;
        case 39:
            var newDate = self.getDate() || new Date();
            do {
                newDate = new Date(newDate.valueOf() + 24*60*60*1000);
            } while (!isAllowedDate(newDate));
            self.setDate(newDate);
            break;
        case 40:
            var newDate = self.getDate() || new Date();
            do {
                newDate = new Date(newDate.valueOf() + 7*24*60*60*1000);
            } while (!isAllowedDate(newDate));
            self.setDate(newDate);
            break;
        case 8:
        case 46:
            self.setDate(null);
            break;
    }
}
